-- AUTO-GENERATED baseline: squash generation 2 (of migrations 00000000000000..00000000000042).
-- 004 · seed: canonical NextBlock demo content (no users, no secrets) — empty databases only
-- Idempotent; safe to replay. Regenerate via tools/scripts/rebaseline-transform.mjs — do not hand-edit.
-- Naming: GGNNN_name.sql (GG = squash generation, NNN = sequence). See docs/04-DATABASE-AND-AUTH.md.

-- Guard: the seed runs ONLY on an empty database. Every existing install (prod, sandbox,
-- downstream) has languages + site_settings rows, so this whole block is a no-op there — the
-- explicit-id INSERTs below must never re-create demo rows an operator deleted.
DO $nb_baseline_seed$
BEGIN
  IF EXISTS (SELECT 1 FROM public.languages) OR EXISTS (SELECT 1 FROM public.site_settings) THEN
    RAISE NOTICE 'baseline seed skipped: database already holds content';
    RETURN;
  END IF;

  text-shadow: 0 0 5px hsl(var(--primary)), 0 0 10px hsl(var(--secondary));
}
& button, & [role="button"] {
  box-shadow: 0 0 5px hsl(var(--primary) / 0.5);
  transition: box-shadow 0.3s ease;
}
& button:hover, & [role="button"]:hover {
  box-shadow: 0 0 15px hsl(var(--primary));
}
& .card, & [class*="card"] {
  border: 1px solid hsl(var(--primary));
  box-shadow: 0 0 10px hsl(var(--primary) / 0.2);
}
& .border {
  border-color: hsl(var(--border));
  box-shadow: 0 0 5px hsl(var(--border) / 0.3);
}', false, false, true, 30, '2026-09-10 15:42:25.171808+00', '2026-09-10 15:42:25.171808+00') ON CONFLICT DO NOTHING;
PERFORM pg_catalog.setval('public.blocks_id_seq', COALESCE((SELECT MAX(id) FROM public.blocks), 1), true);
PERFORM pg_catalog.setval('public.languages_id_seq', COALESCE((SELECT MAX(id) FROM public.languages), 1), true);
PERFORM pg_catalog.setval('public.navigation_items_id_seq', COALESCE((SELECT MAX(id) FROM public.navigation_items), 1), true);
PERFORM pg_catalog.setval('public.page_revisions_id_seq', COALESCE((SELECT MAX(id) FROM public.page_revisions), 1), true);
PERFORM pg_catalog.setval('public.pages_id_seq', COALESCE((SELECT MAX(id) FROM public.pages), 1), true);
PERFORM pg_catalog.setval('public.post_revisions_id_seq', COALESCE((SELECT MAX(id) FROM public.post_revisions), 1), true);
PERFORM pg_catalog.setval('public.posts_id_seq', COALESCE((SELECT MAX(id) FROM public.posts), 1), true);

  -- Born at generation 2: the catch-up file has nothing to replay here.
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
END
$nb_baseline_seed$;
