INSERT INTO public.pages (id, language_id, author_id, title, slug, status, meta_title, meta_description, version, translation_group_id, created_at, updated_at, feature_image_id, custom_canonical, published_at) VALUES (1, 1, NULL, 'Home', 'home', 'published', 'NextBlock: AI Website Builder CMS for Production Sites', 'Build websites fast with the AI website builder CMS that runs on your own AI plan over MCP. Prompt-driven pages land in a production Next.js 16 visual CMS.', 1, '0098e4f0-e5f3-4e28-acfc-bb9fdb3a4a6b', '2026-07-03 17:52:15.479414+00', '2026-09-10 15:42:40.88753+00', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (7, 1, NULL, 'NextBlock Cortex AI Guide', 'nextblock-cortex-ai-guide', 'AI Copilot', 'A practical guide to Cortex AI, the block-aware assistant for model routing, BYOK controls, and faster editorial production inside NextBlock.', 'See how Cortex AI brings structured generation, provider choice, and safer content workflows directly into the NextBlock editor.', 'published', '2026-07-03 17:52:15.643901+00', 'NextBlock Cortex AI Guide', 'Learn how NextBlock Cortex AI helps teams generate, refine, and translate structured block content with model routing and BYOK controls.', '38ec38c2-899f-47b0-8364-56a574527078', 1, '669489e7-5900-496e-8b73-2aba7514a71b', '2026-07-03 17:52:15.643901+00', '2026-07-03 17:52:15.643901+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (3, 1, NULL, 'How to Install NextBlock: Every Setup Option Explained', 'how-to-setup-nextblock', 'Getting Started', 'Every way to install NextBlock — one-click cloud deploy, CLI scaffold, git clone, or self-hosted Docker — with copy-paste steps for each.', 'Four ways to launch NextBlock: a one-click Vercel deploy, npm create nextblock, git clone with the browser setup wizard, or a fully local Docker stack.', 'published', NULL, 'How to Install NextBlock CMS — Vercel, CLI, Git or Docker', 'Install NextBlock in minutes — one-click Vercel deploy, npm create nextblock, git clone, or self-hosted Docker. No config files, no manual SQL.', '77b9da47-4182-470f-9070-fa6cd11c6aea', 1, '461cde55-74cb-4112-8c3d-a25882eeedce', '2026-07-03 17:52:15.479414+00', '2026-07-03 17:52:15.799297+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (4, 2, NULL, 'Installer NextBlock : toutes les options expliquées', 'comment-configurer-nextblock', 'Mise En Route', 'Toutes les façons d''installer NextBlock — cloud en un clic, CLI, git clone ou Docker auto-hébergé — avec les étapes à copier-coller.', 'Quatre façons de lancer NextBlock : déploiement Vercel en un clic, npm create nextblock, git clone avec l''assistant dans le navigateur, ou une pile Docker 100 % locale.', 'published', NULL, 'Installer NextBlock — Vercel, CLI, Git ou Docker', 'Installez NextBlock en quelques minutes : déploiement Vercel en un clic, npm create nextblock, git clone ou Docker auto-hébergé. Sans config ni SQL.', '77b9da47-4182-470f-9070-fa6cd11c6aea', 1, '461cde55-74cb-4112-8c3d-a25882eeedce', '2026-07-03 17:52:15.479414+00', '2026-07-03 17:52:15.799297+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (1, 1, NULL, 'How NextBlock™ Works: A Look Under the Hood', 'how-nextblock-works', 'Architecture', 'Under the hood of the monorepo, block registry, and editor stack that power NextBlock.', 'A guided tour of the monorepo, block registry, editor stack, and open-core architecture behind NextBlock.', 'published', NULL, 'How NextBlock™ Works: Architecture & Under the Hood', 'Explore the architecture behind NextBlock: monorepo packages, typed block registry, Supabase database, and modern Next.js editor stack.', '5bb07d4c-ca14-49ab-96bb-febbed31aded', 1, 'de8b8593-1ef6-4e66-8d1f-8b3e7ffb811d', '2026-07-03 17:52:15.479414+00', '2026-09-10 15:42:40.151677+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (2, 2, NULL, 'Comment NextBlock™ Fonctionne : Regard Sous le Capot', 'comment-nextblock-fonctionne', 'Architecture', 'Sous le capot du monorepo, du registre de blocs et de l editeur qui propulsent NextBlock.', 'Une visite guidee du monorepo, du registre de blocs, de l editeur et de l architecture open-core de NextBlock.', 'published', NULL, 'Comment fonctionne NextBlock™ : Architecture et Moteur', 'Découvrez les fondations de NextBlock : monorepo, registre de blocs typés, base de données Supabase et moteur d''édition Next.js moderne.', '5bb07d4c-ca14-49ab-96bb-febbed31aded', 1, 'de8b8593-1ef6-4e66-8d1f-8b3e7ffb811d', '2026-07-03 17:52:15.479414+00', '2026-09-10 15:42:40.151677+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (5, 1, NULL, 'NextBlock™ Commerce: Multi-Currency, Tax Sync & Beyond', 'nextblock-commerce-guide', 'Commerce', 'Storefront architecture, checkout flows, and premium commerce capabilities inside NextBlock.', 'A closer look at the commerce module, from multi-currency and tax sync to shipping, inventory, and provider-aware checkout.', 'published', NULL, 'The Complete NextBlock™ Commerce Guide | Headless Store', 'Build global e-commerce with NextBlock: manage products, configure multi-currency pricing, and accept payments with headless Stripe checkout.', '5f5a0d6d-aed4-4b6f-b966-ea5d5b17b7a6', 1, '23773a34-e54b-40c6-89b5-b09ead17ae60', '2026-07-03 17:52:15.479414+00', '2026-09-10 15:42:40.151677+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (6, 2, NULL, 'NextBlock™ Commerce : Multi-Devises, Taxes Automatiques et Plus', 'guide-commerce-nextblock', 'Commerce', 'Architecture boutique, parcours de paiement et fonctions commerce premium au coeur de NextBlock.', 'Un apercu du module commerce : multi-devises, sync taxes, expedition, inventaire et paiements connectes.', 'published', NULL, 'Guide Complet du Commerce avec NextBlock™ | E-Commerce', 'Développez votre boutique avec NextBlock : gestion de produits, tarifs multi-devises et tunnel de paiement headless avec Stripe Checkout.', '5f5a0d6d-aed4-4b6f-b966-ea5d5b17b7a6', 1, '23773a34-e54b-40c6-89b5-b09ead17ae60', '2026-07-03 17:52:15.479414+00', '2026-09-10 15:42:40.151677+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (8, 1, NULL, 'How Updating NextBlock Works: One Command for Every Install', 'how-updating-works', 'Maintenance', 'However you installed NextBlock — one-click Vercel, the CLI, Docker or a git clone — a single npm run update brings the code, the dependencies and the database schema forward together.', 'Automatic upstream syncing on Vercel, and one command everywhere else: what npm run update does, what it never touches, and how to roll it back.', 'published', '2026-09-10 15:42:29.557343+00', 'How to Update NextBlock — One Command for Every Install', 'A single command keeps your NextBlock install updated on Docker, Supabase, or a cloned repo. Learn how it works and keeps your data safe.', '3f9c2a7e-6d41-4b8a-9c5e-2a1b7d4e8f60', 1, 'c0d3f1a2-8b47-4e19-9a52-7f6b1d4e8c30', '2026-09-10 15:42:29.557343+00', '2026-09-10 15:42:40.88753+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (9, 2, NULL, 'Les mises à jour de NextBlock : une seule commande, quelle que soit l''installation', 'comment-fonctionnent-les-mises-a-jour', 'Maintenance', 'Quelle que soit votre installation — Vercel en un clic, le CLI, Docker ou un git clone — une seule commande npm run update fait avancer ensemble le code, les dépendances et le schéma de base de données.', 'Synchronisation automatique sur Vercel, et une seule commande partout ailleurs : ce que fait npm run update, ce qu''il ne touche jamais, et comment revenir en arrière.', 'published', '2026-09-10 15:42:29.557343+00', 'Mises à jour NextBlock : une commande pour chaque site', 'Une seule commande met à jour NextBlock sur Docker, Supabase ou un dépôt cloné. Découvrez le fonctionnement et la protection de vos données.', '3f9c2a7e-6d41-4b8a-9c5e-2a1b7d4e8f60', 1, 'c0d3f1a2-8b47-4e19-9a52-7f6b1d4e8c30', '2026-09-10 15:42:29.557343+00', '2026-09-10 15:42:40.88753+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, language_id, author_id, title, slug, label, excerpt, subtitle, status, published_at, meta_title, meta_description, feature_image_id, version, translation_group_id, created_at, updated_at, custom_canonical) VALUES (10, 1, NULL, 'Connect Claude to NextBlock CMS via MCP, from Cursor or Claude Code', 'cortex-ai-mcp-connection-guide', 'Cortex AI', 'Register /api/mcp in Claude Code or Cursor and let your own AI subscription read the schema, draft layouts, and manage pages in NextBlock.', 'A hands-on guide to the Cortex AI MCP server: what it fixes, which tools it exposes, and the exact config for localhost and production.', 'published', '2026-09-10 15:42:40.88753+00', 'Connect Claude to NextBlock CMS via MCP | Cursor Guide', 'Learn how to connect Claude to NextBlock CMS with Model Context Protocol. Register /api/mcp in Claude Code or Cursor to inspect schemas and build layouts.', '8b2e5d1c-9a47-4f3b-8e6d-1c7a2b9d4e50', 1, 'a7c4e2d1-3b58-4f96-9e0a-6d2c8b1f5a73', '2026-09-10 15:42:40.88753+00', '2026-09-10 15:42:40.88753+00', NULL) ON CONFLICT DO NOTHING;
