INSERT INTO public.blocks (id, page_id, post_id, language_id, block_type, content, "order", created_at, updated_at, product_id) VALUES (1, 1, NULL, 1, 'section', '{"is_hero": true, "padding": {"top": "xl", "bottom": "xl"}, "background": {"type": "gradient", "gradient": {"type": "linear", "stops": [{"color": "#020817", "position": 0}, {"color": "#0f172a", "position": 50}, {"color": "#1e293b", "position": 100}], "direction": "135deg"}}, "column_gap": "xl", "column_blocks": [[{"content": {"html_content": "<h1 class=''text-5xl md:text-6xl font-extrabold tracking-tight text-white text-center leading-tight''>Prompt to <span class=''relative inline-block mx-1 group''><span class=''absolute inset-0 bg-gradient-to-r from-blue-600 to-cyan-400 translate-y-1 md:translate-y-2 transform -skew-x-12 rounded-sm shadow-lg group-hover:skew-x-0 transition-transform duration-300 ease-out''></span><span class=''relative text-white italic px-1''>Production</span></span>.<br class=''md:hidden'' /> The AI Website Builder CMS.</h1>"}, "block_type": "text"}, {"content": {"html_content": "<p class=''text-xl text-slate-300 text-center max-w-3xl mx-auto mt-4 leading-relaxed''>NextBlock is the free, open-source AI website builder CMS for teams that want more than a prototype. Add Cortex AI to point Claude Code, Cursor, or ChatGPT at your site over MCP, free for 30 days. You keep a live Next.js 16 and Supabase website with a visual editor your team owns on day two.</p>"}, "block_type": "text"}, {"content": {"url": "https://vercel.com/new/clone?repository-url=https%3A%2F%2Fgithub.com%2Fnextblock-cms%2Fnextblock&project-name=nextblock&repository-name=nextblock&stores=%5B%7B%22type%22%3A%22integration%22%2C%22integrationSlug%22%3A%22supabase%22%2C%22productSlug%22%3A%22supabase%22%7D%5D", "size": "lg", "text": "Deploy to Vercel in One Click", "variant": "default", "position": "center"}, "block_type": "button"}, {"content": {"url": "https://nextblock.dev/product/nextblock-cortex-ai-cortex-ai-license", "size": "lg", "text": "Start the Free Cortex AI Trial", "variant": "outline", "position": "center"}, "block_type": "button"}, {"content": {"html_content": "<div class=''flex flex-wrap justify-center gap-6 text-sm uppercase tracking-wide text-slate-400 mt-8''><a href=''https://github.com/nextblock-cms'' target=''_blank'' rel=''noopener noreferrer'' class=''hover:text-white transition-colors''>GitHub</a><a href=''https://x.com/NextBlockCMS'' target=''_blank'' rel=''noopener noreferrer'' class=''hover:text-white transition-colors''>X</a><a href=''https://www.linkedin.com/in/nextblock/'' target=''_blank'' rel=''noopener noreferrer'' class=''hover:text-white transition-colors''>LinkedIn</a><a href=''https://dev.to/nextblockcms'' target=''_blank'' rel=''noopener noreferrer'' class=''hover:text-white transition-colors''>Dev.to</a><a href=''https://www.npmjs.com/~nextblockcms'' target=''_blank'' rel=''noopener noreferrer'' class=''hover:text-white transition-colors''>npm</a></div>"}, "block_type": "text"}], [{"content": {"html_content": "<div class=''p-10 border border-white/10 rounded-3xl bg-white/5 backdrop-blur-xl shadow-2xl relative overflow-hidden group''><div class=''absolute inset-0 bg-gradient-to-br from-blue-500/10 to-purple-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500''></div><div class=''relative z-10''><p class=''text-xs text-white uppercase tracking-widest font-semibold mb-2''>Up in 10 minutes. Free to start.</p><p class=''text-3xl font-bold text-white mb-2''>Try the whole stack for free.</p><p class=''text-base text-slate-300 mb-6''>The CMS is free forever. Cortex AI, the paid AI layer that includes the MCP server, starts with a 30-day trial and no credit card. One click deploys to Vercel, and you are prompting your own site in ten minutes.</p><ul class=''space-y-3 text-sm text-slate-200''><li><span class=''text-blue-400 mr-2''>&#10003;</span> CMS: free and open source, with unlimited pages, editors, and sites.</li><li><span class=''text-blue-400 mr-2''>&#10003;</span> Cortex AI: 30 days free, no credit card, then one license.</li><li><span class=''text-blue-400 mr-2''>&#10003;</span> Bring your own AI subscription. No token markup, ever.</li></ul><div class=''mt-6 rounded-2xl overflow-hidden border border-white/10 shadow-lg''><div class=''relative w-full aspect-video''><iframe class=''absolute inset-0 h-full w-full border-0'' src=''https://www.youtube-nocookie.com/embed/71MyfoL4YVM?si=jtlDXV6cSC8rDgz0'' title=''NextBlock demo video'' allow=''accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share'' referrerpolicy=''strict-origin-when-cross-origin'' loading=''lazy'' allowfullscreen></iframe></div></div></div></div>"}, "block_type": "text"}]], "container_type": "container", "responsive_columns": {"mobile": 1, "tablet": 1, "desktop": 2}, "vertical_alignment": "center"}', 0, '2026-07-03 17:52:15.479414+00', '2026-09-10 15:42:44.217407+00', NULL) ON CONFLICT DO NOTHING;
